-- 572: Original BrillaPrep WASSCE English Language sprint 3 beta questions, part 2 of 9 (batch wassce-english-sprint3-001).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_572_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_572_guard;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_010' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "Zebilla Senior High reached the regional debating finals. Coach Adongo insisted that facts must be clothed in courtesy. On the day, their opponents spoke louder, but Zebilla spoke better: every claim was supported, every rebuttal polite. The verdict was unanimous, and the trophy rode home on the captain''s knees like a baby." The statement "their opponents spoke louder, but Zebilla spoke better" implies that in debating' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. the loudest team always wins","B. the quality of argument matters more than volume","C. judges prefer quiet contestants","D. opponents should not be heard"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The contrast sets loudness against merit: Zebilla''s supported claims and polite rebuttals — quality, not volume — carried the day, as the unanimous verdict confirms. Therefore the correct answer is B: the quality of argument matters more than volume.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Infer' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_010' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_037' AND NOT (q.topic_id IS 'topic_wassce_english_lexis' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Answer both questions on vocabulary and usage.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) buy (b) up' AND q.explanation IS '(a) "purchase" means buy in this everyday context; (b) the phrasal verb "look up" means to search for information in a reference work, so the missing particle is "up".' AND q.difficulty IS 'medium' AND q.points IS '6' AND q.marks IS '6' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Answer' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_037' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_037_a' AND NOT (sp.id IS 'sqp_q_eng_s3_037_a' AND sp.question_id IS 'q_eng_s3_037' AND sp.part_label IS 'a' AND sp.part_text IS 'Give the word nearest in meaning to "purchase" as used in: "Auntie went to the market to purchase a new cloth."' AND sp.marks IS '3' AND sp.correct_answer IS 'buy' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '0')) THEN 1 ELSE 0 END;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_037_b' AND NOT (sp.id IS 'sqp_q_eng_s3_037_b' AND sp.question_id IS 'q_eng_s3_037' AND sp.part_label IS 'b' AND sp.part_text IS 'Complete with the correct particle: "The students were advised to look ___ every new word in a dictionary."' AND sp.marks IS '3' AND sp.correct_answer IS 'up' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_038' AND NOT (q.topic_id IS 'topic_wassce_english_grammar' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Answer both questions on grammar and usage.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Each of the girls has a locker. (b) The bell was rung by the prefect.' AND q.explanation IS '(a) "each" is singular and takes "has"; "of the girls" only modifies the subject. (b) The object "the bell" becomes the subject of the passive, with "was rung" and the agent introduced by "by".' AND q.difficulty IS 'medium' AND q.points IS '6' AND q.marks IS '6' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Answer' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_038' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_038_a' AND NOT (sp.id IS 'sqp_q_eng_s3_038_a' AND sp.question_id IS 'q_eng_s3_038' AND sp.part_label IS 'a' AND sp.part_text IS 'Correct the concord error in this sentence: "Each of the girls have a locker."' AND sp.marks IS '3' AND sp.correct_answer IS 'Each of the girls has a locker.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '0')) THEN 1 ELSE 0 END;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_038_b' AND NOT (sp.id IS 'sqp_q_eng_s3_038_b' AND sp.question_id IS 'q_eng_s3_038' AND sp.part_label IS 'b' AND sp.part_text IS 'Rewrite the following sentence in the passive voice: "The prefect rang the bell."' AND sp.marks IS '3' AND sp.correct_answer IS 'The bell was rung by the prefect.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_040' AND NOT (q.topic_id IS 'topic_wassce_english_literary_devices' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Name the literary device used in each of the following sentences.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) Personification (b) Metaphor' AND q.explanation IS '(a) Opportunity is given the human action of knocking — personification. (b) Troubles are called a "sea" without "like" or "as" — a metaphor, not a simile.' AND q.difficulty IS 'medium' AND q.points IS '6' AND q.marks IS '6' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Name' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_040' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_040_a' AND NOT (sp.id IS 'sqp_q_eng_s3_040_a' AND sp.question_id IS 'q_eng_s3_040' AND sp.part_label IS 'a' AND sp.part_text IS '"Opportunity knocked on Kofi''s door at last."' AND sp.marks IS '3' AND sp.correct_answer IS 'Personification' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '0')) THEN 1 ELSE 0 END;
INSERT INTO _migration_572_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s3_040_b' AND NOT (sp.id IS 'sqp_q_eng_s3_040_b' AND sp.question_id IS 'q_eng_s3_040' AND sp.part_label IS 'b' AND sp.part_text IS '"After the verdict, he drowned in a sea of troubles."' AND sp.marks IS '3' AND sp.correct_answer IS 'Metaphor' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '1')) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s3_010', 'topic_wassce_p2_eng_cmp', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Read the passage, then answer. — "Zebilla Senior High reached the regional debating finals. Coach Adongo insisted that facts must be clothed in courtesy. On the day, their opponents spoke louder, but Zebilla spoke better: every claim was supported, every rebuttal polite. The verdict was unanimous, and the trophy rode home on the captain''s knees like a baby." The statement "their opponents spoke louder, but Zebilla spoke better" implies that in debating', 'multiple_choice', NULL, '["A. the loudest team always wins","B. the quality of argument matters more than volume","C. judges prefer quiet contestants","D. opponents should not be heard"]', 'B', 'The contrast sets loudness against merit: Zebilla''s supported claims and polite rebuttals — quality, not volume — carried the day, as the unanimous verdict confirms. Therefore the correct answer is B: the quality of argument matters more than volume.', 'hard', '3', '1', '60', NULL, NULL, '1', NULL, NULL, 'Infer', 'AO3', NULL, NULL, NULL);
